    {
      "path": "cordis.patch.yml",
      "content": "# The configuration row this bundle contributes when a profile lists it.\n# Every value falls back to an environment variable so the API key is never\n# hardcoded; alternatively copy this row into the profile's own\n# cordis.patch.yml and fill the values there (file permissions should be\n# restrictive). See README.md.\n#\n# 本插件 bundle 贡献的配置行。所有取值回退到环境变量，API key 绝不硬编码；\n# 也可以把这一行拷进 profile 自己的 cordis.patch.yml 填写实际值。\n- insert:\n    - id: weknora-archive\n      # Must be the published/local package name — the loader imports this specifier.\n      name: dsh-weknora-archive\n      config:\n        # WeKnora deployment root or API root, e.g. http://weknora.example.com\n        # or http://weknora.example.com/api/v1 (placeholder — set your own).\n        baseUrl: !!js process.env.WEKNORA_ARCHIVE_BASE_URL ?? ''\n        # Scoped API key. Sensitive: never log it, never commit it.\n        apiKey: !!js process.env.WEKNORA_ARCHIVE_API_KEY\n        # Default target knowledge base id (optional; auto-created per project when absent).\n        knowledgeBaseId: !!js process.env.WEKNORA_ARCHIVE_KB_ID\n        # DSH sessions root; empty = <harness home>/sessions auto-detected.\n        sessionsDir: !!js process.env.WEKNORA_ARCHIVE_SESSIONS_DIR ?? ''\n        maxSummaryChars: !!js Number(process.env.WEKNORA_ARCHIVE_MAX_SUMMARY_CHARS ?? 8000)\n"
    },
    {
      "path": "lib/index.js",
      "content": "/**\n * dsh-weknora-archive: DeepSeek Harness host plugin that incrementally\n * archives DSH sessions into a WeKnora knowledge base (the write-side\n * complement to the read-only official dsh-weknora plugin).\n * @module dsh-weknora-archive\n */\n\nimport { WeknoraClient } from './client.js';\nimport { resolveConfig, redactConfig } from './config.js';\nimport { listProjectDirs, listSessions } from './session-reader.js';\nimport { archiveProject } from './archive.js';\n\nexport const name = 'dsh-weknora-archive';\n/** Cordis waits for the tool registry before applying this plugin. */\nexport const inject = ['tools'];\n\nexport { resolveConfig, redactConfig } from './config.js';\nexport { WeknoraClient } from './client.js';\nexport { archiveProject } from './archive.js';\n\nconst STRING_ARRAY = { type: 'array', items: { type: 'string' } };\n\n/**\n * Register the agent-facing tools. Each registration is an effect, so\n * unloading or reconfiguring the plugin withdraws them without a restart.\n * @param ctx - the Cordis context with `ctx.tools` injected.\n * @param config - the plugin's `config` row; validated at load time.\n */\nexport function apply(ctx, config) {\n  const resolved = resolveConfig(config);\n  const client = new WeknoraClient(resolved);\n  const log = (message) => {\n    // Config values are never interpolated into logs; only redacted form.\n    ctx.logger?.info?.(`${message} (config: ${JSON.stringify(redactConfig(resolved))})`) ?? console.log(message);\n  };\n  const fail = (error) => {\n    // Defensive: strip any credential material before the error reaches the model.\n    const message = String(error?.message ?? error).split('X-API-Key')[0];\n    throw new Error(`dsh-weknora-archive: ${message}`);\n  };\n  const definitions = [];\n\n  // 1. Archive a project's sessions (extract → summarize → upload, incremental).\n  definitions.push({\n    name: `${resolved.toolPrefix}_session`,\n    description: '把当前机器上某个 DSH 项目的会话增量归档进 WeKnora 知识库：解压会话存储 → 启发式总结 → 按标题去重后上传（知识库不存在时自动按项目名新建）。Archive a DSH project\\'s sessions into a WeKnora knowledge base incrementally: decompress session storage, summarize, dedupe by document title, upload (auto-creates the knowledge base when absent). Use when the user says 归档/archive sessions/更新知识库.',\n    parameters: {\n      type: 'object',\n      properties: {\n        project_keyword: { type: 'string', description: '项目目录名关键词，如 \"my-app\"；模糊匹配 sessions 目录。Project directory keyword to match.' },\n        knowledge_base_id: { type: 'string', description: '可选：目标知识库 id；缺省按配置或按项目名自动匹配/新建。' },\n        dry_run: { type: 'boolean', description: '可选：只统计将要归档的会话，不上传。Preview without uploading.' },\n      },\n      required: ['project_keyword'],\n      additionalProperties: false,\n    },\n    timeoutMs: resolved.uploadTimeoutMs,\n    isConcurrencySafe: () => false,\n    output: {\n      schema: {\n        type: 'object',\n        properties: {\n          ok: { type: 'boolean' },\n          knowledge_base_id: { type: 'string' },\n          created: { type: 'boolean' },\n          uploaded_count: { type: 'integer' },\n          skipped_count: { type: 'integer' },\n          detail: { type: 'string' },\n        },\n        required: ['ok'],\n        additionalProperties: false,\n      },\n      render: (_args, value) => [{ type: 'text', text: value.detail ?? JSON.stringify(value) }],\n    },\n    async execute(args) {\n      try {\n        const result = await archiveProject({ client, config: resolved }, {\n          projectKeyword: args.project_keyword,\n          knowledgeBaseId: args.knowledge_base_id,\n          dryRun: args.dry_run === true,\n        });\n        if (!result.ok) return { ok: false, detail: result.error };\n        return {\n          ok: true,\n          knowledge_base_id: result.knowledgeBaseId,\n          created: result.created,\n          uploaded_count: result.uploaded.length,\n          skipped_count: result.skippedCount,\n          detail: [\n            `项目 ${result.project} (${result.projectDir})`,\n            `知识库 ${result.knowledgeBaseId}${result.created ? '（新建）' : ''}`,\n            `${result.dryRun ? '预览：将上传' : '已上传'} ${result.uploaded.length} 篇，跳过已归档 ${result.skippedCount} 篇（共 ${result.totalSessions} 个会话）`,\n            result.overview ? `总览文档：${result.overview}` : null,\n            ...result.uploaded.map((entry) => `- ${entry.title} (${entry.chars} chars)`),\n          ].filter(Boolean).join('\\n'),\n        };\n      } catch (error) {\n        return fail(error);\n      }\n    },\n  });\n\n  // 2. Archive status: projects, sessions, and per-project archive state.\n  definitions.push({\n    name: `${resolved.toolPrefix}_status`,\n    description: '查看归档状态：列出本机 DSH 会话项目目录与各自会话数，以及目标知识库内的归档文档标题。Show archive status: local DSH session project directories with session counts, and the document titles already in the target knowledge base. Read-only.',\n    parameters: {\n      type: 'object',\n      properties: {\n        project_keyword: { type: 'string', description: '可选：只看匹配的项目。Optional filter.' },\n        knowledge_base_id: { type: 'string', description: '可选：查看该库内的文档。Optional KB to inspect.' },\n      },\n      additionalProperties: false,\n    },\n    timeoutMs: resolved.requestTimeoutMs,\n    isConcurrencySafe: () => true,\n    output: {\n      schema: {\n        type: 'object',\n        properties: { ok: { type: 'boolean' }, detail: { type: 'string' } },\n        required: ['ok', 'detail'],\n        additionalProperties: false,\n      },\n      render: (_args, value) => [{ type: 'text', text: value.detail }],\n    },\n    async execute(args) {\n      try {\n        const dirs = listProjectDirs(resolved.sessionsDir)\n          .filter((dir) => !args.project_keyword || dir.toLowerCase().includes(String(args.project_keyword).toLowerCase()));\n        const lines = dirs.map((dir) => {\n          let count = '?';\n          try {\n            count = String(listSessions(resolved.sessionsDir, dir).length);\n          } catch { /* unreadable dir */ }\n          return `- ${dir} (${count} sessions)`;\n        });\n        if (args.knowledge_base_id) {\n          const docs = await client.listKnowledge(args.knowledge_base_id);\n          lines.push(`知识库 ${args.knowledge_base_id} 文档 ${docs.length} 篇:`);\n          for (const doc of docs.slice(0, 50)) {\n            lines.push(`- ${doc?.title ?? doc?.knowledge_title ?? '(untitled)'} [${doc?.parse_status ?? '?'}]`);\n          }\n        }\n        return { ok: true, detail: lines.length > 0 ? lines.join('\\n') : '未找到匹配的会话项目目录。' };\n      } catch (error) {\n        return fail(error);\n      }\n    },\n  });\n\n  // 3. List knowledge bases (base create/list capability, write-side).\n  definitions.push({\n    name: `${resolved.toolPrefix}_list_knowledge_bases`,\n    description: '列出该 WeKnora 凭据可见的知识库（id 与名称），用于选择归档目标。List the WeKnora knowledge bases this credential can see, with ids. Read-only.',\n    parameters: { type: 'object', properties: {}, additionalProperties: false },\n    timeoutMs: resolved.requestTimeoutMs,\n    isConcurrencySafe: () => true,\n    output: {\n      schema: {\n        type: 'object',\n        properties: {\n          ok: { type: 'boolean' },\n          detail: { type: 'string' },\n        },\n        required: ['ok', 'detail'],\n        additionalProperties: false,\n      },\n      render: (_args, value) => [{ type: 'text', text: value.detail }],\n    },\n    async execute() {\n      try {\n        const bases = await client.listKnowledgeBases();\n        const detail = bases.length === 0\n          ? '该凭据没有可见的知识库。'\n          : `${bases.length} 个知识库:\\n${bases.map((kb) => `- ${kb?.name ?? '?'} (id: ${kb?.id ?? '?'})`).join('\\n')}`;\n        return { ok: true, detail };\n      } catch (error) {\n        return fail(error);\n      }\n    },\n  });\n\n  // 4. Create a knowledge base.\n  definitions.push({\n    name: `${resolved.toolPrefix}_create_knowledge_base`,\n    description: '新建一个 WeKnora 知识库（名称 + 一句话描述）。注意：新建后可能需要在 WeKnora 端配置 embedding 模型，否则文档解析会失败。Create a WeKnora knowledge base (name + short description). Note: a freshly created KB may need an embedding model configured on the WeKnora side before documents parse.',\n    parameters: {\n      type: 'object',\n      properties: {\n        name: { type: 'string', description: '知识库名称。KB name.' },\n        description: { type: 'string', description: '一句话描述。Short description.' },\n      },\n      required: ['name'],\n      additionalProperties: false,\n    },\n    timeoutMs: resolved.requestTimeoutMs,\n    isConcurrencySafe: () => false,\n    output: {\n      schema: {\n        type: 'object',\n        properties: {\n          ok: { type: 'boolean' },\n          detail: { type: 'string' },\n        },\n        required: ['ok', 'detail'],\n        additionalProperties: false,\n      },\n      render: (_args, value) => [{ type: 'text', text: value.detail }],\n    },\n    async execute(args) {\n      try {\n        const result = await client.createKnowledgeBase(args.name, args.description ?? '');\n        const id = result?.id ?? result?.data?.id ?? '';\n        return { ok: true, detail: `已创建知识库 ${args.name} (id: ${id})。如文档解析失败，请先在 WeKnora 端为该库配置 embedding 模型。` };\n      } catch (error) {\n        return fail(error);\n      }\n    },\n  });\n\n  for (const definition of definitions) ctx.tools.register(definition);\n  log(`dsh-weknora-archive: registered ${definitions.map((d) => d.name).join(', ')}`);\n}\n"
    },
    {
      "path": "lib/archive.js",
      "content": "/**\n * Archive orchestration: incremental find-new → summarize → create-or-update\n * knowledge base → upload. Pure orchestration over injected client + reader,\n * so tests can substitute mocks.\n * @module dsh-weknora-archive/archive\n */\n\nimport { listSessions, readSessionText } from './session-reader.js';\nimport { summarizeSession, summarizeProjectOverview } from './summarizer.js';\n\n/** Doc title convention must match the session-archive skill: `会话总结: <project>_<sessionId8>`. */\nexport function sessionDocTitle(projectName, sessionId) {\n  // Session ids look like `session-<uuid>` or a bare `<uuid>`; both carry a\n  // long `session-` prefix that a plain slice(0, 8) would swallow whole.\n  const tail = String(sessionId).replace(/^session-/, '');\n  const short = tail.length > 8 ? tail.slice(0, 8) : tail;\n  return `会话总结: ${projectName}_${short}`;\n}\n\n/**\n * Compute which sessions are new relative to existing document titles.\n * @returns string[] of sessionIds not yet archived.\n */\nexport function findNewSessions(sessions, existingTitles) {\n  const known = new Set([...existingTitles].map((title) => String(title).split('_').at(-1)));\n  return sessions\n    .map((session) => session.sessionId)\n    .filter((id) => {\n      const tail = String(id).replace(/^session-/, '');\n      const short = tail.length > 8 ? tail.slice(0, 8) : tail;\n      return !known.has(short);\n    });\n}\n\n/**\n * Run one archive pass against a project.\n * @param deps - { client, config, log }\n * @param options - { projectKeyword, dryRun, knowledgeBaseId }\n */\nexport async function archiveProject(deps, options) {\n  const { client, config, log } = deps;\n  const { matchProjectDirs } = await import('./session-reader.js');\n  const dirs = matchProjectDirs(config.sessionsDir, options.projectKeyword);\n  if (dirs.length === 0) {\n    return { ok: false, error: `no session project dir matches keyword \"${options.projectKeyword}\" under ${config.sessionsDir}` };\n  }\n  if (dirs.length > 1) {\n    return { ok: false, error: `keyword \"${options.projectKeyword}\" is ambiguous, matches: ${dirs.join(', ')}` };\n  }\n  const projectDir = dirs[0];\n  // dsh encodes a project path by collapsing `/`, `\\` and `:` into a single `-`\n  // (see session-persistence-jsonl/format.ts), wrapping the slug in `--…--`.\n  // `--data--` is the project `data`; `--Users-me-demo--` is `Users/me/demo`.\n  const projectName = projectDir.replace(/^-+|-+$/g, '').split('-').filter(Boolean).at(-1) ?? projectDir;\n  const sessions = listSessions(config.sessionsDir, projectDir);\n\n  // Resolve target knowledge base (explicit id → config default → match by name → create).\n  let knowledgeBaseId = options.knowledgeBaseId || config.knowledgeBaseId;\n  let created = false;\n  if (!knowledgeBaseId) {\n    const bases = await client.listKnowledgeBases();\n    const matched = bases.find((kb) => kb?.name === projectName);\n    if (matched) {\n      knowledgeBaseId = matched.id;\n    } else {\n      const result = await client.createKnowledgeBase(projectName, `DSH session archive for ${projectDir} (by dsh-weknora-archive)`);\n      knowledgeBaseId = result?.id ?? result?.data?.id ?? '';\n      created = true;\n    }\n  }\n  if (!knowledgeBaseId) return { ok: false, error: 'could not resolve or create a target knowledge base' };\n\n  const existing = await client.listKnowledge(knowledgeBaseId);\n  const existingTitles = new Set(existing.map((doc) => doc?.title ?? doc?.knowledge_title ?? ''));\n  // WeKnora titles a document after the uploaded FILE, so the library shows\n  // `data_xxx.md` while the intended title is `会话总结: data_xxx`. Compare on\n  // the session key so both spellings deduplicate.\n  const isArchived = (title) => {\n    if (existingTitles.has(title)) return true;\n    const key = title.replace(/^会话总结: /, '').replace(/\\.md$/i, '');\n    return [...existingTitles].some((existingTitle) =>\n      existingTitle.replace(/\\.md$/i, '').endsWith(key));\n  };\n\n  const uploaded = [];\n  const skipped = [];\n  const isFirstRun = existingTitles.size === 0;\n  for (const session of sessions) {\n    const title = sessionDocTitle(projectName, session.sessionId);\n    if (isArchived(title)) {\n      skipped.push(session.sessionId);\n      continue;\n    }\n    const text = readSessionText(session.filePath);\n    if (text.messages.length === 0) {\n      skipped.push(session.sessionId);\n      continue;\n    }\n    const summary = summarizeSession(text, { projectName, maxChars: config.maxSummaryChars });\n    if (options.dryRun) {\n      uploaded.push({ sessionId: session.sessionId, title, dryRun: true, chars: summary.markdown.length });\n      continue;\n    }\n    const filename = `${sessionDocTitle(projectName, session.sessionId).replace(/^会话总结: /, '')}.md`;\n    try {\n      await client.uploadKnowledge({ knowledgeBaseId, title, content: summary.markdown, filename });\n      uploaded.push({ sessionId: session.sessionId, title, filename, chars: summary.markdown.length });\n    } catch (err) {\n      // WeKnora answers 409 duplicate_file when a same-named document already\n      // exists. The pre-upload title check misses it whenever a previous run\n      // uploaded before its document became listable, so treat it as a skip\n      // rather than aborting the whole pass.\n      if (err?.status === 409) {\n        skipped.push(session.sessionId);\n        continue;\n      }\n      throw err;\n    }\n  }\n\n  // First run also contributes a project overview.\n  let overview = null;\n  if (isFirstRun && !options.dryRun && uploaded.length > 0) {\n    overview = summarizeProjectOverview({ projectName, projectDir, sessions, summaries: uploaded });\n    try {\n      await client.uploadKnowledge({\n        knowledgeBaseId,\n        title: overview.title,\n        content: overview.markdown,\n        filename: '00_项目总览.md',\n      });\n    } catch (err) {\n      if (err?.status !== 409) throw err;   // an existing overview is fine\n      overview = null;\n    }\n  }\n\n  log?.info(`dsh-weknora-archive: ${projectName} → kb ${knowledgeBaseId}: ${uploaded.length} uploaded, ${skipped.length} skipped`);\n  return {\n    ok: true,\n    knowledgeBaseId,\n    created,\n    project: projectName,\n    projectDir,\n    totalSessions: sessions.length,\n    uploaded,\n    skippedCount: skipped.length,\n    overview: overview ? overview.title : null,\n    dryRun: Boolean(options.dryRun),\n  };\n}\n"
    },
    {
      "path": "lib/session-reader.js",
      "content": "/**\n * Read DSH session storage (read-only, in-process) and extract plain\n * conversation text from `session.v3.jsonl.zstd` files.\n *\n * Layout: `<sessionsRoot>/<encodedProjectDir>/<sessionId>/session.v3.jsonl.zstd`\n * where encodedProjectDir is the absolute project path with `/` replaced by\n * `--`. Extraction rules follow the session-archive skill: `user/message`\n * events carry `data.content[].text`; `assistant/attempt` events carry\n * `data.stream[].chunk.text`.\n * @module dsh-weknora-archive/session-reader\n */\n\nimport { readdirSync, readFileSync, statSync, existsSync } from 'node:fs';\nimport { join } from 'node:path';\nimport { zstdDecompressSync } from 'node:zlib';\n\n/** zstd frame magic number (little-endian 0xFD2FB528). */\nconst ZSTD_MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);\n\n/**\n * Decompress a file made of MANY concatenated zstd frames.\n *\n * dsh >= 0.2 writes one frame per flush instead of a single stream, so\n * `zstdDecompressSync` only returns the first frame (session metadata) and\n * silently drops every conversation event after it. Walk the buffer and\n * decompress at each magic offset instead.\n *\n * @param {Buffer} buf raw file bytes\n * @returns {string} concatenated decompressed text\n */\nfunction decompressConcatenatedFrames(buf) {\n  const parts = [];\n  let pos = 0;\n  // Frames are dense; a failed offset just means a magic byte inside payload\n  // data, so keep scanning rather than giving up on the first error.\n  while (pos < buf.length) {\n    const idx = buf.indexOf(ZSTD_MAGIC, pos);\n    if (idx === -1) break;\n    try {\n      parts.push(zstdDecompressSync(buf.subarray(idx)));\n    } catch {\n      // Not a real frame boundary — skip this byte and rescan.\n    }\n    pos = idx + 1;\n  }\n  return Buffer.concat(parts).toString('utf8');\n}\n\n/** Session file names, newest format first. */\nconst SESSION_FILES = ['session.v4.jsonl.zstd', 'session.v3.jsonl.zstd'];\n\n/** Assistant event names carrying the reply stream. */\nconst ASSISTANT_EVENTS = new Set(['assistant/message', 'assistant/attempt']);\n\n/**\n * List project directories under the sessions root.\n * @returns string[] of encoded project directory names.\n */\nexport function listProjectDirs(sessionsRoot) {\n  return readdirSync(sessionsRoot, { withFileTypes: true })\n    .filter((entry) => entry.isDirectory() && entry.name.startsWith('--'))\n    .map((entry) => entry.name)\n    .sort();\n}\n\n/** Fuzzy-match project dirs by keyword (case-insensitive substring). */\nexport function matchProjectDirs(sessionsRoot, keyword) {\n  const dirs = listProjectDirs(sessionsRoot);\n  if (!keyword) return dirs;\n  const needle = keyword.toLowerCase();\n  return dirs.filter((dir) => dir.toLowerCase().includes(needle));\n}\n\n/**\n * Read one session file and extract ordered plain conversation text.\n * @returns {{ sessionId: string, messages: Array<{role: 'user'|'assistant', text: string}>, bytes: number }}\n */\nexport function readSessionText(sessionFilePath) {\n  const compressed = readFileSync(sessionFilePath);\n  const jsonl = decompressConcatenatedFrames(compressed);\n  const sessionId = sessionFilePath.split('/').at(-2) ?? '';\n  const messages = [];\n  for (const line of jsonl.split('\\n')) {\n    if (line.trim() === '') continue;\n    let event;\n    try {\n      event = JSON.parse(line);\n    } catch {\n      continue; // tolerate trailing partial lines on live sessions\n    }\n    if (event?.type === 'user/message') {\n      const text = (event?.data?.content ?? [])\n        .filter((block) => block?.type === 'text' && typeof block.text === 'string')\n        .map((block) => block.text)\n        .join('\\n');\n      if (text.trim() !== '') messages.push({ role: 'user', text });\n    } else if (ASSISTANT_EVENTS.has(event?.type)) {\n      // v4 keeps the final reply in data.message.content (same shape as\n      // user/message) and uses data.stream only for incremental deltas;\n      // v3 carried the text directly in the stream entries.\n      const blocks = event?.data?.message?.content\n        ?? (event?.data?.stream ?? []).map((entry) => entry?.chunk ?? entry);\n      const text = (blocks ?? [])\n        .filter((block) => block?.type === 'text' && typeof block.text === 'string')\n        .map((block) => block.text)\n        .join('');\n      if (text.trim() !== '') {\n        const last = messages.at(-1);\n        if (last?.role === 'assistant') last.text += `\\n${text}`;\n        else messages.push({ role: 'assistant', text });\n      }\n    }\n  }\n  return { sessionId, messages, bytes: compressed.length };\n}\n\n/**\n * List sessions of one project with mtime and size metadata.\n * @returns Array<{ sessionId: string, dir: string, filePath: string, mtimeMs: number, size: number }>\n */\nexport function listSessions(sessionsRoot, projectDir) {\n  const base = join(sessionsRoot, projectDir);\n  const out = [];\n  for (const entry of readdirSync(base, { withFileTypes: true })) {\n    if (!entry.isDirectory()) continue;\n    const filePath = SESSION_FILES\n      .map((name) => join(base, entry.name, name))\n      .find((candidate) => existsSync(candidate));\n    if (!filePath) continue;\n    let stats;\n    try {\n      stats = statSync(filePath);\n    } catch {\n      continue;\n    }\n    out.push({ sessionId: entry.name, dir: entry.name, filePath, mtimeMs: stats.mtimeMs, size: stats.size });\n  }\n  return out.sort((a, b) => a.mtimeMs - b.mtimeMs);\n}\n"
    },
    {
      "path": "lib/summarizer.js",
      "content": "/**\n * Heuristic (LLM-free) session summarizer. Produces one Markdown summary per\n * session following the session-archive template: time range, topic, key\n * decisions/outputs, artifacts, pitfalls, hard details, leftovers. Designed to\n * be unit-testable against mock session data.\n * @module dsh-weknora-archive/summarizer\n */\n\nconst PATH_PATTERN = /(?:\\/[\\w.@~-]+){2,}/g;\nconst COMMAND_PATTERN = /(?:^|\\s)((?:npm|pnpm|node|git|curl|docker|brew|bash)\\s[^\\n`\"]{3,120})/g;\nconst NOISE_PATTERN = /\\b(429|rate.?limit|retrying|retry \\d+)\\b/i;\n\n/**\n * Harness-injected blocks that look like user turns but carry no topic.\n * dsh prepends these to the first user message of every session, so a naive\n * \"first user line is the topic\" rule summarizes the runtime context instead\n * of the question.\n */\nconst INJECTED_BLOCK_PATTERNS = [\n  /^<system-reminder>/im,\n  /^Current runtime context\\./im,\n  /^Time sampled while preparing turn/im,\n  /^\\s*#\\s*AGENTS\\.md/m,\n  /<available_skills>/i,\n  /^The user (?:referenced|attached|approved|denied)/im,\n  /^\\[?\\s*(?:image|attachment)\\b.*\\bsha256:/im,\n];\n\n/** Task-template / role-play prompts: instructions, not the user's own ask. */\nconst TEMPLATE_LINE_PATTERNS = [\n  /^你是[「『\"']/,\n  /^你扮演/,\n  /^请扮演/,\n  /^作为(一个|一名)/,\n  /^\\s*\\d+\\.\\s*(?:先执行|命令缺失)/,\n  /^\\s*-\\s*类型：cordis/,\n  /^\\s*-\\s*简介：/,\n  /^\\s*-\\s*参考命令/,\n  /^\\s*【.+】/,\n  /^current working directory:/im,\n  // DSH plugin-installer template metadata (\"是否需要配置\" / \"目标 profile\" …)\n  /^\\s*-\\s*需要配置[：:]/,\n  /^\\s*-\\s*目标\\s*profile[：:]/i,\n  /^\\s*-\\s*前序尝试/,\n  /^\\s*-\\s*插件信息/,\n  /^\\s*插件名[：:]/,\n];\n\n/** True when a single line reads as template boilerplate instead of substance. */\nfunction isTemplateLine(line) {\n  return TEMPLATE_LINE_PATTERNS.some((pattern) => pattern.test(line));\n}\n\n/**\n * Split a message into lines worth treating as real user intent.\n *\n * dsh often prepends the runtime block and a task template to the very first\n * user message, while the real question shares that same message. So filtering\n * happens per line, never per message: dropping a whole message would lose the\n * question, and keeping it whole would let the runtime context become the topic.\n *\n * Multi-line blocks (`Current runtime context:` … until a blank line) are cut as\n * a unit, because only their first line carries the marker.\n */\nfunction meaningfulLines(text) {\n  const raw = text.split(/\\n+/).map((line) => line.trim());\n  const out = [];\n  let skippingBlock = false;\n  for (const line of raw) {\n    if (line === '') { skippingBlock = false; continue; }   // blank line ends a block\n    if (INJECTED_BLOCK_PATTERNS.some((pattern) => pattern.test(line))) {\n      skippingBlock = true;\n      continue;\n    }\n    if (skippingBlock) continue;\n    if (line.length < 4 || line.length > 400) continue;\n    if (isTemplateLine(line)) continue;\n    if (isNoise(line)) continue;\n    out.push(line);\n  }\n  return out;\n}\n\nfunction clip(text, max) {\n  const trimmed = text.replace(/\\s+/g, ' ').trim();\n  return trimmed.length <= max ? trimmed : `${trimmed.slice(0, max)}…`;\n}\n\nfunction isNoise(text) {\n  return NOISE_PATTERN.test(text) && text.length < 80;\n}\n\n/**\n * Summarize one session's extracted messages.\n * @param session - { sessionId, messages: [{role, text}] }\n * @param options - { projectName, maxChars }\n * @returns {{ title: string, markdown: string, firstTs: string|undefined, lastTs: string|undefined }}\n */\nexport function summarizeSession(session, { projectName = 'project', maxChars = 8000 } = {}) {\n  const lines = [];\n  const userTurns = session.messages.filter((m) => m.role === 'user');\n  const assistantTurns = session.messages.filter((m) => m.role === 'assistant');\n  const contentful = session.messages.filter((m) => !isNoise(m.text));\n\n  // Only user lines that survive scaffolding removal can describe the topic.\n  const userIntent = userTurns.flatMap((turn) => meaningfulLines(turn.text));\n\n  const decisions = [];\n  const details = new Set();\n  const commands = new Set();\n  const paths = new Set();\n  for (const message of contentful) {\n    for (const match of message.text.matchAll(COMMAND_PATTERN)) commands.add(clip(match[1], 120));\n    for (const match of message.text.matchAll(PATH_PATTERN)) {\n      if (!match[0].includes('node_modules')) details.add(clip(match[0], 160));\n    }\n  }\n  // Decisions come from user lines too, but keep only those that read like a\n  // statement of intent rather than a fragment of a longer system block.\n  for (const line of userIntent) {\n    if (decisions.length >= 8) break;\n    if (line.length < 12) continue;\n    if (/[.。!！?？]$/.test(line) || line.includes('：') || line.includes(': ')) {\n      decisions.push(clip(line, 200));\n    }\n  }\n  const toolNames = new Set();\n  for (const turn of assistantTurns) {\n    for (const match of turn.text.matchAll(/\\b(?:weknora_[a-z_]+|todo_write|subagent|workflow|bash|read|write|edit|grep|glob)\\b/g)) {\n      toolNames.add(match[1]);\n    }\n  }\n\n  // Topic: the first real user lines, longest-first within the opening turns.\n  const topics = userIntent.slice(0, 3).map((line) => clip(line, 120));\n  const chars = session.messages.reduce((sum, m) => sum + m.text.length, 0);\n  const idTail = String(session.sessionId ?? '').replace(/^session-/, '');\n  const shortId = idTail.length > 8 ? idTail.slice(0, 8) : idTail;\n  const title = `会话总结: ${projectName}_${shortId}`;\n\n  lines.push(`# ${title}`);\n  lines.push('');\n  lines.push(`- **主题**: ${topics.length > 0 ? topics.join(' / ') : '(无用户输入)'}`);\n  lines.push(`- **体量**: ${session.messages.length} 条消息 / 约 ${chars} 字符${assistantTurns.length === 0 ? '；[派工型会话：仅任务书无回复]' : ''}`);\n  if (decisions.length > 0) {\n    lines.push('- **关键决策与结论**:');\n    for (const decision of decisions.slice(0, 8)) lines.push(`  1. ${decision}`);\n  }\n  if (commands.size > 0) {\n    lines.push('- **产出与命令**:');\n    for (const command of [...commands].slice(0, 6)) lines.push(`  - \\`${command}\\``);\n  }\n  if (paths.size > 0) {\n    lines.push('- **重要细节（路径/端口/配置）**:');\n    for (const path of [...paths].slice(0, 8)) lines.push(`  - ${path}`);\n  }\n  if (toolNames.size > 0) lines.push(`- **使用的工具**: ${[...toolNames].slice(0, 12).join(', ')}`);\n  lines.push('- **未完成/遗留**: 以会话末尾为准，未发现显式遗留事项' );\n  lines.push('');\n  lines.push('> 由 dsh-weknora-archive 启发式总结生成（无 LLM 参与）；凭据类内容一律未收录完整值。');\n\n  let markdown = lines.join('\\n');\n  if (markdown.length > maxChars) markdown = `${markdown.slice(0, maxChars)}\\n…(截断)`;\n  return { title, markdown };\n}\n\n/**\n * Build the project-overview document for a first archive run.\n */\nexport function summarizeProjectOverview({ projectName, projectDir, sessions, summaries }) {\n  const lines = [\n    `# 项目总览: ${projectName}`,\n    '',\n    `- **会话目录**: ${projectDir}`,\n    `- **归档会话数**: ${sessions.length}`,\n    `- **本次归档**: ${summaries.length} 篇会话总结`,\n    '',\n    '## 会话清单',\n    '',\n    ...summaries.map((summary) => `- ${summary.title}`),\n    '',\n    '> 由 dsh-weknora-archive 自动生成。',\n  ];\n  return { title: `项目总览: ${projectName}`, markdown: lines.join('\\n') };\n}\n"
    },
    {
      "path": "lib/client.js",
      "content": "/**\n * Minimal write-side WeKnora HTTP client (RESTful, aligned with the endpoints\n * the read-only dsh-weknora plugin and Tencent WeKnora document; routes use\n * kebab-case `/knowledge-bases` and auth is the `X-API-Key` header — NOT\n * Bearer). If a deployment diverges, only this module needs adjusting; see\n * README \"API compatibility\".\n * @module dsh-weknora-archive/client\n */\n\nimport { normalizeBaseUrl } from './config.js';\n\n/** Error carrying HTTP status; message never includes the API key. */\nexport class WeknoraApiError extends Error {\n  constructor(status, method, path, bodySnippet) {\n    super(`WeKnora ${method} ${path} failed with HTTP ${status}: ${bodySnippet}`);\n    this.name = 'WeknoraApiError';\n    this.status = status;\n  }\n}\n\nexport class WeknoraClient {\n  /**\n   * @param config - resolved plugin config (baseUrl normalized, apiKey present).\n   */\n  constructor(config) {\n    this.baseUrl = config.baseUrl;\n    this.apiKey = config.apiKey;\n    this.requestTimeoutMs = config.requestTimeoutMs;\n    this.uploadTimeoutMs = config.uploadTimeoutMs;\n  }\n\n  headers(extra = {}) {\n    return { 'X-API-Key': this.apiKey, ...extra };\n  }\n\n  async request(method, path, { json, timeoutMs, expect = [200] } = {}) {\n    const controller = new AbortController();\n    const timer = setTimeout(() => controller.abort(), timeoutMs ?? this.requestTimeoutMs);\n    try {\n      const response = await fetch(`${this.baseUrl}${path}`, {\n        method,\n        headers: this.headers(json !== undefined ? { 'Content-Type': 'application/json' } : {}),\n        body: json !== undefined ? JSON.stringify(json) : undefined,\n        signal: controller.signal,\n      });\n      const text = await response.text();\n      if (!expect.includes(response.status)) {\n        throw new WeknoraApiError(response.status, method, path, text.slice(0, 300));\n      }\n      try {\n        return text === '' ? {} : JSON.parse(text);\n      } catch {\n        return { raw: text };\n      }\n    } finally {\n      clearTimeout(timer);\n    }\n  }\n\n  /** GET /knowledge-bases */\n  listKnowledgeBases(signal) {\n    return this.request('GET', '/knowledge-bases', { timeoutMs: signal?.timeoutMs }).then(\n      (body) => Array.isArray(body?.data) ? body.data : (Array.isArray(body) ? body : []),\n    );\n  }\n\n  /** POST /knowledge-bases — { name, description } */\n  createKnowledgeBase(name, description) {\n    return this.request('POST', '/knowledge-bases', {\n      json: { name, description: description ?? '' },\n      expect: [200, 201],\n    });\n  }\n\n  /** GET /knowledge-bases/{id}/knowledge?page_size=100 — list documents. */\n  listKnowledge(knowledgeBaseId) {\n    return this.request('GET', `/knowledge-bases/${encodeURIComponent(knowledgeBaseId)}/knowledge?page_size=100`)\n      .then((body) => Array.isArray(body?.data) ? body.data : (Array.isArray(body) ? body : []));\n  }\n\n  /**\n   * POST /knowledge-bases/{id}/knowledge/file — upload one Markdown document.\n   *\n   * This deployment exposes the multipart upload under the knowledge-base\n   * scoped `/knowledge/file` route (taken from the WeKnora web client's own\n   * request), not the flat `/knowledge` route used by the upstream docs.\n   */\n  async uploadKnowledge({ knowledgeBaseId, title, content, filename }) {\n    const controller = new AbortController();\n    const timer = setTimeout(() => controller.abort(), this.uploadTimeoutMs);\n    const path = `/knowledge-bases/${encodeURIComponent(knowledgeBaseId)}/knowledge/file`;\n    try {\n      const form = new FormData();\n      form.append('file', new Blob([new TextEncoder().encode(content)], { type: 'text/markdown' }),\n        filename ?? `${title}.md`);\n      const response = await fetch(`${this.baseUrl}${path}`, {\n        method: 'POST',\n        headers: this.headers(),\n        body: form,\n        signal: controller.signal,\n      });\n      const text = await response.text();\n      if (response.status !== 200 && response.status !== 201) {\n        throw new WeknoraApiError(response.status, 'POST', path, text.slice(0, 300));\n      }\n      try {\n        return JSON.parse(text);\n      } catch {\n        return { raw: text };\n      }\n    } finally {\n      clearTimeout(timer);\n    }\n  }\n\n  /** POST /knowledge/{id}/reparse — retry parsing a failed document. */\n  reparse(knowledgeId) {\n    return this.request('POST', `/knowledge/${encodeURIComponent(knowledgeId)}/reparse`, { expect: [200, 201, 202] });\n  }\n\n  /** GET /knowledge/{id} — poll parse status of one document. */\n  getKnowledge(knowledgeId) {\n    return this.request('GET', `/knowledge/${encodeURIComponent(knowledgeId)}`);\n  }\n}\n\nexport { normalizeBaseUrl };\n"
    },
    {
      "path": "lib/config.js",
      "content": "/**\n * Plugin configuration: shape, defaults and load-time validation.\n * The API key is sensitive: it is never included in log output, error\n * messages, or tool results — see redactConfig().\n * @module dsh-weknora-archive/config\n */\n\nconst DEFAULTS = {\n  baseUrl: '',\n  apiKey: '',\n  knowledgeBaseId: '',\n  sessionsDir: '',\n  maxSummaryChars: 8000,\n  requestTimeoutMs: 30_000,\n  uploadTimeoutMs: 120_000,\n  toolPrefix: 'weknora_archive',\n};\n\nconst API_ROOT = /\\/api\\/v\\d+$/;\nconst TOOL_PREFIX = /^[a-z][a-z0-9_]*$/;\n\n/** Error thrown when the config row cannot be served; message never embeds the key. */\nexport class ConfigError extends Error {\n  constructor(violations) {\n    super(`dsh-weknora-archive configuration is invalid:\\n  - ${violations.join('\\n  - ')}`);\n    this.name = 'ConfigError';\n  }\n}\n\n/**\n * Normalize a WeKnora base URL to an API root. Both `http://host` and\n * `http://host/api/v1` are accepted, mirroring the official dsh-weknora plugin.\n */\nexport function normalizeBaseUrl(raw) {\n  const trimmed = String(raw).trim().replace(/\\/+$/, '');\n  return API_ROOT.test(trimmed) ? trimmed : `${trimmed}/api/v1`;\n}\n\nfunction optionalString(value, field, violations) {\n  if (value === undefined || value === null) return '';\n  if (typeof value !== 'string') {\n    violations.push(`${field} must be a string`);\n    return '';\n  }\n  return value.trim();\n}\n\nfunction positiveInt(value, field, violations, fallback) {\n  if (value === undefined || value === null || value === '') return fallback;\n  const n = Number(value);\n  if (!Number.isFinite(n) || n <= 0) {\n    violations.push(`${field} must be a positive number, received ${JSON.stringify(value)}`);\n    return fallback;\n  }\n  return Math.floor(n);\n}\n\n/**\n * Apply defaults and reject an unusable row at load time, so a typo surfaces\n * at boot rather than inside the first tool call.\n * @param raw - the `config` value from the Cordis row.\n */\nexport function resolveConfig(raw) {\n  const violations = [];\n  const input = (typeof raw === 'object' && raw !== null && !Array.isArray(raw)) ? raw : {};\n  const baseUrlRaw = optionalString(input.baseUrl, 'baseUrl', violations);\n  let baseUrl = '';\n  if (baseUrlRaw === '') {\n    violations.push('baseUrl is required (your WeKnora deployment root or API root)');\n  } else {\n    try {\n      const url = new URL(normalizeBaseUrl(baseUrlRaw));\n      if (url.protocol !== 'http:' && url.protocol !== 'https:') {\n        violations.push(`baseUrl must use http or https, received ${url.protocol}`);\n      }\n      baseUrl = url.toString().replace(/\\/+$/, '');\n    } catch {\n      violations.push(`baseUrl must be an absolute URL, received a malformed value`);\n    }\n  }\n  const apiKey = optionalString(input.apiKey, 'apiKey', violations);\n  if (apiKey === '') violations.push('apiKey is required (a scoped WeKnora API key with ingest capability)');\n  const toolPrefix = optionalString(input.toolPrefix, 'toolPrefix', violations) || DEFAULTS.toolPrefix;\n  if (!TOOL_PREFIX.test(toolPrefix)) {\n    violations.push(`toolPrefix must match ${String(TOOL_PREFIX)}, received a malformed value`);\n  }\n  const config = {\n    baseUrl,\n    apiKey,\n    knowledgeBaseId: optionalString(input.knowledgeBaseId, 'knowledgeBaseId', violations),\n    sessionsDir: optionalString(input.sessionsDir, 'sessionsDir', violations),\n    maxSummaryChars: positiveInt(input.maxSummaryChars, 'maxSummaryChars', violations, DEFAULTS.maxSummaryChars),\n    requestTimeoutMs: positiveInt(input.requestTimeoutMs, 'requestTimeoutMs', violations, DEFAULTS.requestTimeoutMs),\n    uploadTimeoutMs: positiveInt(input.uploadTimeoutMs, 'uploadTimeoutMs', violations, DEFAULTS.uploadTimeoutMs),\n    toolPrefix,\n  };\n  if (violations.length > 0) throw new ConfigError(violations);\n  return config;\n}\n\n/**\n * Return a copy of the config safe for logging: the key is replaced by a\n * fixed placeholder. Use this for every log/error path.\n */\nexport function redactConfig(config) {\n  return { ...config, apiKey: '(redacted)' };\n}\n"
    },
    {
      "path": "test/mock.test.mjs",
      "content": "/**\n * Local unit test for dsh-weknora-archive: runs the summarizer and the\n * incremental archive pipeline against mock session data and a mock WeKnora\n * client. No network access, no real credentials. Run: `npm test` or\n * `node test/mock.test.mjs`.\n */\nimport assert from 'node:assert/strict';\nimport { mkdtempSync, mkdirSync, writeFileSync } from 'node:fs';\nimport { tmpdir } from 'node:os';\nimport { join } from 'node:path';\nimport { zstdCompressSync } from 'node:zlib';\nimport { summarizeSession, summarizeProjectOverview } from '../lib/summarizer.js';\nimport { findNewSessions, sessionDocTitle, archiveProject } from '../lib/archive.js';\nimport { resolveConfig, redactConfig, normalizeBaseUrl } from '../lib/config.js';\n\n// ---- mock WeKnora client ---------------------------------------------------\nclass MockClient {\n  constructor(bases = [], docs = {}) {\n    this.bases = bases.map((b) => ({ ...b }));\n    this.docs = new Map(Object.entries(docs).map(([k, v]) => [k, v.map((d) => ({ ...d }))]));\n  }\n  async listKnowledgeBases() { return this.bases; }\n  async createKnowledgeBase(name, description) {\n    const id = `kb-${this.bases.length + 1}`;\n    this.bases.push({ id, name, description });\n    this.docs.set(id, []);\n    return { id };\n  }\n  async listKnowledge(kbId) { return this.docs.get(kbId) ?? []; }\n  async uploadKnowledge({ knowledgeBaseId, title }) {\n    this.docs.get(knowledgeBaseId)?.push({ title, parse_status: 'completed' });\n    return { knowledge_id: `k-${title.length}` };\n  }\n}\n\n// ---- tiny test runner (sync + async) ---------------------------------------\nlet passed = 0;\nconst failures = [];\nasync function check(name, fn) {\n  try {\n    await fn();\n    passed++;\n    console.log(`  ok - ${name}`);\n  } catch (error) {\n    failures.push(`${name}: ${error.message}`);\n    console.error(`  FAIL - ${name}: ${error.message}`);\n  }\n}\n\n// ---- config ----------------------------------------------------------------\nconsole.log('config:');\nawait check('normalizeBaseUrl appends /api/v1', () => {\n  assert.equal(normalizeBaseUrl('http://localhost:8090'), 'http://localhost:8090/api/v1');\n  assert.equal(normalizeBaseUrl('http://localhost:8090/api/v1/'), 'http://localhost:8090/api/v1');\n});\nawait check('resolveConfig rejects missing baseUrl/apiKey', () => {\n  assert.throws(() => resolveConfig({}), /baseUrl is required/);\n});\nawait check('resolveConfig accepts a full config', () => {\n  const cfg = resolveConfig({ baseUrl: 'http://x.example', apiKey: 'sk-secret-abc', sessionsDir: '/tmp/s' });\n  assert.equal(cfg.baseUrl, 'http://x.example/api/v1');\n});\nawait check('redactConfig hides the key', () => {\n  const cfg = resolveConfig({ baseUrl: 'http://x.example', apiKey: 'sk-secret-abc' });\n  assert.ok(!JSON.stringify(redactConfig(cfg)).includes('sk-secret-abc'));\n});\n\n// ---- summarizer ------------------------------------------------------------\nconsole.log('summarizer:');\nawait check('summarizeSession follows the template', () => {\n  const session = {\n    sessionId: 'abcdef1234567890',\n    messages: [\n      { role: 'user', text: '请把 /Users/hechao/project/foo 的接口对接到 pnpm build 流程里，端口 8090' },\n      { role: 'assistant', text: '已完成：修改了 index.js 并运行 node --check 通过。' },\n    ],\n  };\n  const { title, markdown } = summarizeSession(session, { projectName: 'foo' });\n  assert.equal(title, '会话总结: foo_abcdef12');\n  assert.ok(markdown.includes('**主题**'));\n  assert.ok(markdown.includes('8090'));\n  assert.ok(!markdown.toLowerCase().includes('sk-'));\n});\nawait check('empty-assistant session is marked dispatch-only', () => {\n  const { markdown } = summarizeSession(\n    { sessionId: 'ffffffff', messages: [{ role: 'user', text: '任务书内容很长很长很长很长' }] },\n    { projectName: 'p' },\n  );\n  assert.ok(markdown.includes('派工型会话'));\n});\nawait check('project overview lists summaries', () => {\n  const overview = summarizeProjectOverview({\n    projectName: 'p', projectDir: '--x--', sessions: [{}, {}], summaries: [{ title: '会话总结: p_aa' }],\n  });\n  assert.ok(overview.markdown.includes('会话总结: p_aa'));\n});\n\n// ---- archive pipeline (mock) ----------------------------------------------\nconsole.log('archive pipeline (mock):');\nconst root = mkdtempSync(join(tmpdir(), 'dsh-wa-test-'));\nconst PROJECT = '--Users-me-demo--';\nfunction writeFakeSession(sessionId, userText, assistantText) {\n  const dir = join(root, PROJECT, sessionId);\n  mkdirSync(dir, { recursive: true });\n  const lines = [\n    JSON.stringify({ type: 'user/message', data: { content: [{ type: 'text', text: userText }] } }),\n    JSON.stringify({ type: 'assistant/attempt', data: { stream: [{ type: 'text', text: assistantText }] } }),\n  ];\n  writeFileSync(join(dir, 'session.v3.jsonl.zstd'), zstdCompressSync(Buffer.from(lines.join('\\n'))));\n}\nwriteFakeSession('session-11111111', '修复登录 bug，路径 /srv/app/login.ts', 'done, ran git commit');\nwriteFakeSession('session-22222222', '新增导出功能', 'ok');\nfunction writeFakeSessionIn(projectDir, sessionId, userText, assistantText) {\n  const dir = join(root, projectDir, sessionId);\n  mkdirSync(dir, { recursive: true });\n  const lines = [\n    JSON.stringify({ type: 'user/message', data: { content: [{ type: 'text', text: userText }] } }),\n    JSON.stringify({ type: 'assistant/attempt', data: { stream: [{ type: 'text', text: assistantText }] } }),\n  ];\n  writeFileSync(join(dir, 'session.v3.jsonl.zstd'), zstdCompressSync(Buffer.from(lines.join('\\n'))));\n}\nwriteFakeSessionIn('--Users-me-demo2--', 'session-33333333', '另一个项目', 'ok');\nconst config = resolveConfig({ baseUrl: 'http://weknora.invalid', apiKey: 'sk-test', sessionsDir: root });\n\nawait check('first run creates KB, uploads all + overview', async () => {\n  const client = new MockClient();\n  const first = await archiveProject({ client, config }, { projectKeyword: 'demo--' });\n  assert.equal(first.ok, true);\n  assert.equal(first.created, true);\n  assert.equal(first.uploaded.length, 2);\n  assert.equal(first.overview, '项目总览: demo');\n});\nawait check('second run dedupes: uploads nothing, skips all', async () => {\n  const client = new MockClient();\n  await archiveProject({ client, config }, { projectKeyword: 'demo--' });\n  const second = await archiveProject({ client, config }, { projectKeyword: 'demo--' });\n  assert.equal(second.ok, true);\n  assert.equal(second.created, false);\n  assert.equal(second.uploaded.length, 0);\n  assert.equal(second.skippedCount, 2);\n});\nawait check('findNewSessions skips archived titles', () => {\n  const sessions = [{ sessionId: 'aaaaaaaa' }, { sessionId: 'bbbbbbbb' }];\n  const fresh = findNewSessions(sessions, [sessionDocTitle('x', 'aaaaaaaa')]);\n  assert.deepEqual(fresh, ['bbbbbbbb']);\n});\nawait check('ambiguous keyword errors cleanly', async () => {\n  const client = new MockClient();\n  const result = await archiveProject({ client, config }, { projectKeyword: '--Users-me' });\n  assert.equal(result.ok, false);\n  assert.ok(result.error.includes('ambiguous'));\n});\n\nif (failures.length > 0) {\n  console.error(`\\n${failures.length} test(s) FAILED, ${passed} passed`);\n  process.exit(1);\n}\nconsole.log(`\\nall ${passed} tests passed`);\n"
    }
  ],
